        ["Connected to GitHub."] = ["Connected to GitHub.", "Verbonden met GitHub.", "Mit GitHub verbunden.", "Connecté à GitHub."],
        ["GitHub CLI is not authenticated. Run gh auth login."] = ["GitHub CLI is not authenticated. Run gh auth login.", "GitHub CLI is niet aangemeld. Voer gh auth login uit.", "GitHub CLI ist nicht angemeldet. Führen Sie gh auth login aus.", "GitHub CLI n’est pas authentifié. Exécutez gh auth login."],
        ["Connected to Azure DevOps."] = ["Connected to Azure DevOps.", "Verbonden met Azure DevOps.", "Mit Azure DevOps verbunden.", "Connecté à Azure DevOps."],
        ["Azure DevOps CLI extension is unavailable. Install it with: az extension add --name azure-devops"] = ["Azure DevOps CLI extension is unavailable. Install it with: az extension add --name azure-devops", "De Azure DevOps CLI-extensie ontbreekt. Installeer deze met: az extension add --name azure-devops", "Die Azure-DevOps-CLI-Erweiterung fehlt. Installieren Sie sie mit: az extension add --name azure-devops", "L’extension CLI Azure DevOps est indisponible. Installez-la avec : az extension add --name azure-devops"],
        ["Enter an Azure DevOps organization to check access."] = ["Enter an Azure DevOps organization to check access.", "Voer een Azure DevOps-organisatie in om toegang te controleren.", "Geben Sie eine Azure-DevOps-Organisation ein, um den Zugriff zu prüfen.", "Saisissez une organisation Azure DevOps pour vérifier l’accès."],
        ["Sign in to Azure CLI with az login before using Azure DevOps."] = ["Sign in to Azure CLI with az login before using Azure DevOps.", "Meld je met az login aan bij Azure CLI voordat je Azure DevOps gebruikt.", "Melden Sie sich mit az login bei Azure CLI an, bevor Sie Azure DevOps verwenden.", "Connectez-vous à Azure CLI avec az login avant d’utiliser Azure DevOps."],
        ["Azure CLI is signed in. Azure DevOps organization access will be checked when selected."] = ["Azure CLI is signed in. Azure DevOps organization access will be checked when selected.", "Je bent aangemeld bij Azure CLI. Toegang tot Azure DevOps wordt gecontroleerd zodra je een organisatie kiest.", "Azure CLI ist angemeldet. Der Zugriff auf die Azure-DevOps-Organisation wird nach Auswahl geprüft.", "Azure CLI est connecté. L’accès à l’organisation Azure DevOps sera vérifié après sélection."],
        ["Azure DevOps access could not be verified for this organization."] = ["Azure DevOps access could not be verified for this organization.", "Toegang tot Azure DevOps kon voor deze organisatie niet worden gecontroleerd.", "Der Azure-DevOps-Zugriff für diese Organisation konnte nicht überprüft werden.", "L’accès à Azure DevOps n’a pas pu être vérifié pour cette organisation."],
        ["No Azure DevOps projects were returned."] = ["No Azure DevOps projects were returned.", "Azure DevOps heeft geen projecten teruggegeven.", "Azure DevOps hat keine Projekte zurückgegeben.", "Azure DevOps n’a renvoyé aucun projet."],
        ["No repositories were found."] = ["No repositories were found.", "Geen repositories gevonden.", "Keine Repositories gefunden.", "Aucun dépôt trouvé."],
        ["No projects were found."] = ["No projects were found.", "Geen projecten gevonden.", "Keine Projekte gefunden.", "Aucun projet trouvé."],
        ["No authenticated Git hosting provider is available. Install and sign in to GitHub CLI (gh) or Azure CLI with the Azure DevOps extension (az)."] = ["No authenticated Git hosting provider is available. Install and sign in to GitHub CLI (gh) or Azure CLI with the Azure DevOps extension (az).", "Geen ingelogde Git-provider beschikbaar. Installeer en meld je aan bij GitHub CLI (gh) of Azure CLI met de Azure DevOps-extensie (az).", "Kein angemeldeter Git-Anbieter verfügbar. Installieren Sie GitHub CLI (gh) oder Azure CLI mit Azure-DevOps-Erweiterung (az) und melden Sie sich an.", "Aucun fournisseur Git authentifié n’est disponible. Installez et connectez-vous à GitHub CLI (gh) ou Azure CLI avec l’extension Azure DevOps (az)."],
        ["No Git hosting CLI connection detected. You can still clone by entering a Git URL."] = ["No Git hosting CLI connection detected. You can still clone by entering a Git URL.", "Geen Git-hosting-CLI-verbinding gevonden. Je kunt nog steeds clonen door een Git-URL in te voeren.", "Keine Git-Hosting-CLI-Verbindung gefunden. Sie können weiterhin klonen, indem Sie eine Git-URL eingeben.", "Aucune connexion à une CLI d’hébergement Git détectée. Vous pouvez tout de même cloner en saisissant une URL Git."],
        ["Select an authenticated Git hosting provider to create a remote repository."] = ["Select an authenticated Git hosting provider to create a remote repository.", "Selecteer een ingelogde Git-provider om een remote repository aan te maken.", "Wählen Sie einen angemeldeten Git-Anbieter aus, um ein Remote-Repository zu erstellen.", "Sélectionnez un fournisseur Git authentifié pour créer un dépôt distant."],
        ["Configure your Git {0} before creating a repository."] = ["Configure your Git {0} before creating a repository.", "Stel je Git-{0} in voordat je een repository maakt.", "Konfigurieren Sie Ihren Git-{0}, bevor Sie ein Repository erstellen.", "Configurez votre {0} Git avant de créer un dépôt."],
        ["The destination folder must be empty."] = ["The destination folder must be empty.", "De doelmap moet leeg zijn.", "Der Zielordner muss leer sein.", "Le dossier de destination doit être vide."],
        ["The destination folder must be empty or a Git repository."] = ["The destination folder must be empty or a Git repository.", "De doelmap moet leeg zijn of een Git-repository bevatten.", "Der Zielordner muss leer sein oder ein Git-Repository enthalten.", "Le dossier de destination doit être vide ou contenir un dépôt Git."],
        ["The selected folder is already a Git repository. Choose Use existing remote instead."] = ["The selected folder is already a Git repository. Choose Use existing remote instead.", "De gekozen map is al een Git-repository. Kies in plaats daarvan ‘Bestaande remote gebruiken’.", "Der ausgewählte Ordner ist bereits ein Git-Repository. Wählen Sie stattdessen „Vorhandenes Remote verwenden“.", "Le dossier sélectionné est déjà un dépôt Git. Choisissez plutôt « Utiliser un dépôt distant existant »."],
        ["Use existing remote requires an existing Git repository with an origin remote."] = ["Use existing remote requires an existing Git repository with an origin remote.", "‘Bestaande remote gebruiken’ vereist een bestaande Git-repository met een origin-remote.", "„Vorhandenes Remote verwenden“ erfordert ein Git-Repository mit Origin-Remote.", "L’option « Utiliser un dépôt distant existant » nécessite un dépôt Git avec un origin."],
        ["The local repository already has a different origin remote: {0}"] = ["The local repository already has a different origin remote: {0}", "De lokale repository heeft al een andere origin-remote: {0}", "Das lokale Repository hat bereits ein anderes Origin-Remote: {0}", "Le dépôt local possède déjà un origin différent : {0}"],
        ["The local repository does not have an origin remote."] = ["The local repository does not have an origin remote.", "De lokale repository heeft geen origin-remote.", "Das lokale Repository hat kein Origin-Remote.", "Le dépôt local ne possède pas d’origin."],
        ["The destination path is already a file."] = ["The destination path is already a file.", "Het doelpad is al een bestand.", "Der Zielpfad ist bereits eine Datei.", "Le chemin de destination est déjà un fichier."],
        ["The destination path already exists."] = ["The destination path already exists.", "Het doelpad bestaat al.", "Der Zielpfad ist bereits vorhanden.", "Le chemin de destination existe déjà."],
        ["GitHub did not return the new repository URL."] = ["GitHub did not return the new repository URL.", "GitHub heeft geen URL van de nieuwe repository teruggegeven.", "GitHub hat keine URL für das neue Repository zurückgegeben.", "GitHub n’a pas renvoyé l’URL du nouveau dépôt."],
        ["GitHub created the repository but its clone URL could not be found."] = ["GitHub created the repository but its clone URL could not be found.", "GitHub heeft de repository gemaakt, maar de clone-URL kon niet worden gevonden.", "GitHub hat das Repository erstellt, aber die Klon-URL wurde nicht gefunden.", "GitHub a créé le dépôt, mais son URL de clonage est introuvable."],
        ["Azure DevOps did not return the new repository URL."] = ["Azure DevOps did not return the new repository URL.", "Azure DevOps heeft geen URL van de nieuwe repository teruggegeven.", "Azure DevOps hat keine URL für das neue Repository zurückgegeben.", "Azure DevOps n’a pas renvoyé l’URL du nouveau dépôt."],
        ["{0} is not installed or is not available in PATH."] = ["{0} is not installed or is not available in PATH.", "{0} is niet geïnstalleerd of niet beschikbaar in PATH.", "{0} ist nicht installiert oder nicht im PATH verfügbar.", "{0} n’est pas installé ou n’est pas disponible dans PATH."],
        ["Could not start {0}."] = ["Could not start {0}.", "{0} kon niet worden gestart.", "{0} konnte nicht gestartet werden.", "Impossible de démarrer {0}."],
        ["The selected destination folder does not exist."] = ["The selected destination folder does not exist.", "De geselecteerde doelmap bestaat niet.", "Der ausgewählte Zielordner existiert nicht.", "Le dossier de destination sélectionné n’existe pas."],
        ["A private repository will be created in your authenticated GitHub account."] = ["A private repository will be created in your authenticated GitHub account.", "Er wordt een private repository gemaakt in je ingelogde GitHub-account.", "In Ihrem angemeldeten GitHub-Konto wird ein privates Repository erstellt.", "Un dépôt privé sera créé dans votre compte GitHub connecté."],
        ["A new repository will be created in the selected Azure DevOps project."] = ["A new repository will be created in the selected Azure DevOps project.", "Er wordt een nieuwe repository gemaakt in het geselecteerde Azure DevOps-project.", "Im ausgewählten Azure-DevOps-Projekt wird ein neues Repository erstellt.", "Un nouveau dépôt sera créé dans le projet Azure DevOps sélectionné."],
        ["Add a repository folder to get started."] = ["Add a repository folder to get started.", "Voeg een repositorymap toe om te beginnen.", "Fügen Sie einen Repository-Ordner hinzu, um zu beginnen.", "Ajoutez un dossier de dépôt pour commencer."],
