        ["Preparing temporary access to real repository files..."] = ["Preparing temporary access to real repository files...", "Tijdelijke toegang tot echte repositorybestanden voorbereiden...", "Temporären Zugriff auf Repository-Dateien vorbereiten...", "Préparation de l’accès temporaire aux fichiers réels..."],
        ["Maximum per file (MB)"] = ["Maximum per file (MB)", "Maximum per bestand (MB)", "Maximum pro Datei (MB)", "Maximum par fichier (Mo)"],
        ["Maximum total selection (MB)"] = ["Maximum total selection (MB)", "Maximum totale selectie (MB)", "Maximum Gesamtauswahl (MB)", "Maximum de la sélection totale (Mo)"],
        ["Applies to new sandbox sessions. Larger limits increase disk and memory use."] = ["Applies to new sandbox sessions. Larger limits increase disk and memory use.", "Geldt voor nieuwe sandboxsessies. Hogere limieten gebruiken meer schijfruimte en geheugen.", "Gilt für neue Sandbox-Sitzungen. Höhere Grenzen erhöhen den Speicher- und Festplattenbedarf.", "S’applique aux nouvelles sessions. Des limites plus élevées augmentent l’utilisation du disque et de la mémoire."],
        ["Enabled"] = ["Enabled", "Ingeschakeld", "Aktiviert", "Activé"],
        ["Permissions"] = ["Permissions", "Toestemmingen", "Berechtigungen", "Autorisations"],
        ["Sandbox settings"] = ["Sandbox settings", "Sandboxinstellingen", "Sandbox-Einstellungen", "Paramètres du bac à sable"],
        ["Sandbox startup model"] = ["Sandbox startup model", "Sandbox-startmodel", "Sandbox-Startmodell", "Modèle de démarrage du bac à sable"],
        ["Saved file selections are copied automatically on startup. Review these files for secrets before saving."] = ["Saved file selections are copied automatically on startup. Review these files for secrets before saving.", "Opgeslagen bestandsselecties worden bij het starten automatisch gekopieerd. Controleer deze bestanden vóór opslaan op secrets.", "Gespeicherte Dateiauswahlen werden beim Start automatisch kopiert. Prüfen Sie sie vor dem Speichern auf Geheimnisse.", "Les fichiers sélectionnés sont copiés automatiquement au démarrage. Vérifiez leurs secrets avant d’enregistrer."],
        ["Sandbox starts automatically using the model and reviewed files configured in Sandbox settings."] = ["Sandbox starts automatically using the model and reviewed files configured in Sandbox settings.", "De sandbox start automatisch met het model en de gecontroleerde bestanden uit Sandboxinstellingen.", "Die Sandbox startet automatisch mit dem Modell und den geprüften Dateien aus den Sandbox-Einstellungen.", "Le bac à sable démarre automatiquement avec le modèle et les fichiers vérifiés des paramètres."],
        ["Preparing sandbox terminal..."] = ["Preparing sandbox terminal...", "Sandboxterminal voorbereiden...", "Sandbox-Terminal vorbereiten...", "Préparation du terminal du bac à sable..."],
        ["Loading sandbox startup model..."] = ["Loading sandbox startup model...", "Sandbox-startmodel laden...", "Sandbox-Startmodell laden...", "Chargement du modèle de démarrage..."],
        ["Copying reviewed files and starting isolated OpenCode..."] = ["Copying reviewed files and starting isolated OpenCode...", "Gecontroleerde bestanden kopiëren en geïsoleerde OpenCode starten...", "Geprüfte Dateien kopieren und isoliertes OpenCode starten...", "Copie des fichiers vérifiés et démarrage d’OpenCode isolé..."],
        ["Stopping sandbox and capturing changes..."] = ["Stopping sandbox and capturing changes...", "Sandbox stoppen en wijzigingen vastleggen...", "Sandbox stoppen und Änderungen erfassen...", "Arrêt du bac à sable et capture des modifications..."],
        ["Existing OpenCode provider/model"] = ["Existing OpenCode provider/model", "Bestaande OpenCode-provider/model", "Vorhandener OpenCode-Anbieter/Modell", "Fournisseur/modèle OpenCode existant"],
        ["Could not read existing OpenCode configuration."] = ["Could not read existing OpenCode configuration.", "Bestaande OpenCode-configuratie lezen mislukt.", "Vorhandene OpenCode-Konfiguration konnte nicht gelesen werden.", "Impossible de lire la configuration OpenCode existante."],
        ["Sandbox uses a supported provider from your existing OpenCode configuration. MCP integration is not available yet; direct network remains blocked."] = ["Sandbox uses a supported provider from your existing OpenCode configuration. MCP integration is not available yet; direct network remains blocked.", "De sandbox gebruikt een ondersteunde provider uit je bestaande OpenCode-configuratie. MCP-integratie is nog niet beschikbaar; direct netwerk blijft geblokkeerd.", "Die Sandbox verwendet einen unterstützten Anbieter aus Ihrer OpenCode-Konfiguration. MCP ist noch nicht verfügbar; direkter Netzwerkzugriff bleibt blockiert.", "Le bac à sable utilise un fournisseur pris en charge de votre configuration OpenCode. MCP n’est pas encore disponible ; le réseau direct reste bloqué."],
        ["Sandbox active"] = ["Sandbox active", "Sandbox actief", "Sandbox aktiv", "Bac à sable actif"],
        ["Sandbox enabled; not running"] = ["Sandbox enabled; not running", "Sandbox aan; niet gestart", "Sandbox aktiviert; nicht gestartet", "Bac à sable activé ; arrêté"],
        ["Experimental sandbox: only selected files are copied. Direct network and MCP are blocked. Only an OpenAI-compatible provider is supported."] = ["Experimental sandbox: only selected files are copied. Direct network and MCP are blocked. Only an OpenAI-compatible provider is supported.", "Experimentele sandbox: alleen geselecteerde bestanden worden gekopieerd. Direct netwerk en MCP zijn geblokkeerd. Alleen een OpenAI-compatible provider wordt ondersteund.", "Experimentelle Sandbox: Nur ausgewählte Dateien werden kopiert. Direkter Netzwerkzugriff und MCP sind blockiert. Nur OpenAI-kompatible Anbieter werden unterstützt.", "Bac à sable expérimental : seuls les fichiers sélectionnés sont copiés. Le réseau direct et MCP sont bloqués. Seul un fournisseur compatible OpenAI est pris en charge."],
        ["OpenCode executable path"] = ["OpenCode executable path", "Pad naar OpenCode-executable", "Pfad zur OpenCode-Programmdatei", "Chemin de l’exécutable OpenCode"],
        ["Reviewed relative file paths (one per line)"] = ["Reviewed relative file paths (one per line)", "Gecontroleerde relatieve bestandspaden (één per regel)", "Geprüfte relative Dateipfade (einer pro Zeile)", "Chemins relatifs vérifiés (un par ligne)"],
        ["items"] = ["items", "items", "Einträge", "éléments"],
        ["No selectable files or folders were found in this repository."] = ["No selectable files or folders were found in this repository.", "Geen selecteerbare bestanden of mappen in deze repository gevonden.", "Keine auswählbaren Dateien oder Ordner in diesem Repository gefunden.", "Aucun fichier ou dossier sélectionnable trouvé dans ce dépôt."],
        ["Selected files and folders are copied automatically on startup. Review selected content for secrets; detection is not guaranteed."] = ["Selected files and folders are copied automatically on startup. Review selected content for secrets; detection is not guaranteed.", "Geselecteerde bestanden en mappen worden bij het starten gekopieerd. Controleer ze op secrets; detectie is niet gegarandeerd.", "Ausgewählte Dateien und Ordner werden beim Start kopiert. Prüfen Sie sie auf Geheimnisse; eine Erkennung ist nicht garantiert.", "Les fichiers et dossiers sélectionnés sont copiés au démarrage. Vérifiez les secrets ; leur détection n’est pas garantie."],
        ["Could not read sandbox settings: {0}"] = ["Could not read sandbox settings: {0}", "Sandboxinstellingen lezen mislukt: {0}", "Sandbox-Einstellungen konnten nicht gelesen werden: {0}", "Impossible de lire les paramètres du bac à sable : {0}"],
        ["Review files for secrets before selection. Unknown secrets cannot be detected automatically."] = ["Review files for secrets before selection. Unknown secrets cannot be detected automatically.", "Controleer bestanden op secrets voordat je ze selecteert. Onbekende secrets worden niet automatisch herkend.", "Prüfen Sie Dateien vor der Auswahl auf Geheimnisse. Unbekannte Geheimnisse werden nicht automatisch erkannt.", "Vérifiez les secrets avant de sélectionner les fichiers. Les secrets inconnus ne sont pas détectés automatiquement."],
        ["Start isolated OpenCode"] = ["Start isolated OpenCode", "Geïsoleerde OpenCode starten", "Isoliertes OpenCode starten", "Démarrer OpenCode isolé"],
        ["Stop sandbox and review changes"] = ["Stop sandbox and review changes", "Sandbox stoppen en wijzigingen beoordelen", "Sandbox stoppen und Änderungen prüfen", "Arrêter le bac à sable et examiner les modifications"],
        ["Configure an OpenAI-compatible API provider in Settings first."] = ["Configure an OpenAI-compatible API provider in Settings first.", "Configureer eerst een OpenAI-compatible API-provider in Instellingen.", "Konfigurieren Sie zuerst einen OpenAI-kompatiblen API-Anbieter in den Einstellungen.", "Configurez d’abord un fournisseur API compatible OpenAI dans les paramètres."],
        ["Only the selected files will be copied. Confirm you have reviewed them for secrets."] = ["Only the selected files will be copied. Confirm you have reviewed them for secrets.", "Alleen geselecteerde bestanden worden gekopieerd. Bevestig dat je ze op secrets hebt gecontroleerd.", "Nur ausgewählte Dateien werden kopiert. Bestätigen Sie, dass Sie sie auf Geheimnisse geprüft haben.", "Seuls les fichiers sélectionnés seront copiés. Confirmez leur vérification pour les secrets."],
        ["Experimental sandbox starts manually from the repository tab. Select reviewed files and configure an API provider first."] = ["Experimental sandbox starts manually from the repository tab. Select reviewed files and configure an API provider first.", "De experimentele sandbox start handmatig vanaf de repositorytab. Selecteer gecontroleerde bestanden en configureer eerst een API-provider.", "Die experimentelle Sandbox wird manuell im Repository-Tab gestartet. Wählen Sie geprüfte Dateien und konfigurieren Sie einen API-Anbieter.", "Le bac à sable expérimental démarre manuellement depuis l’onglet du dépôt. Sélectionnez les fichiers vérifiés et configurez un fournisseur API."],
        ["Revoking permission stops the repository sandbox. Host API keys are never shown here."] = ["Revoking permission stops the repository sandbox. Host API keys are never shown here.", "Toestemming intrekken stopt de repositorysandbox. API-sleutels van de host worden hier nooit getoond.", "Das Entziehen einer Berechtigung stoppt die Repository-Sandbox. Host-API-Schlüssel werden hier nie angezeigt.", "Révoquer une autorisation arrête le bac à sable du dépôt. Les clés API de l’hôte ne sont jamais affichées ici."],
        ["Discard captured sandbox changes"] = ["Discard captured sandbox changes", "Vastgelegde sandboxwijzigingen weggooien", "Erfasste Sandbox-Änderungen verwerfen", "Supprimer les modifications du bac à sable enregistrées"],
        ["Discard the captured changes? They will no longer be available for review."] = ["Discard the captured changes? They will no longer be available for review.", "Vastgelegde wijzigingen weggooien? Ze zijn daarna niet meer beschikbaar voor beoordeling.", "Erfasste Änderungen verwerfen? Sie sind danach nicht mehr zur Prüfung verfügbar.", "Supprimer les modifications enregistrées ? Elles ne seront plus disponibles pour examen."],
        ["Allow sandbox network access?"] = ["Allow sandbox network access?", "Sandbox-netwerktoegang toestaan?", "Sandbox-Netzwerkzugriff erlauben?", "Autoriser l’accès réseau du bac à sable ?"],
        ["Allowing this destination may send repository content to it. The permission is saved for this repository and can be revoked."] = ["Allowing this destination may send repository content to it. The permission is saved for this repository and can be revoked.", "Toestemming voor deze bestemming kan repository-inhoud ernaartoe versturen. De toestemming wordt voor deze repository opgeslagen en kan worden ingetrokken.", "Die Freigabe dieses Ziels kann Repository-Inhalte dorthin übertragen. Die Berechtigung wird für dieses Repository gespeichert und kann widerrufen werden.", "Autoriser cette destination peut lui transmettre le contenu du dépôt. L’autorisation est enregistrée pour ce dépôt et peut être révoquée."],
        ["Allow destination"] = ["Allow destination", "Bestemming toestaan", "Ziel erlauben", "Autoriser la destination"],
        ["Reject"] = ["Reject", "Weigeren", "Ablehnen", "Refuser"],
        ["Review sandbox changes"] = ["Review sandbox changes", "Sandboxwijzigingen beoordelen", "Sandbox-Änderungen prüfen", "Examiner les modifications du bac à sable"],
        ["Selected modifications replace existing files after conflict checks and backup. Deletions and new files are not applied."] = ["Selected modifications replace existing files after conflict checks and backup. Deletions and new files are not applied.", "Geselecteerde wijzigingen vervangen bestaande bestanden na conflictcontrole en back-up. Verwijderingen en nieuwe bestanden worden niet toegepast.", "Ausgewählte Änderungen ersetzen vorhandene Dateien nach Konfliktprüfung und Sicherung. Löschungen und neue Dateien werden nicht angewendet.", "Les modifications sélectionnées remplacent les fichiers existants après vérification des conflits et sauvegarde. Les suppressions et nouveaux fichiers ne sont pas appliqués."],
        ["No captured sandbox changes."] = ["No captured sandbox changes.", "Geen vastgelegde sandboxwijzigingen.", "Keine erfassten Sandbox-Änderungen.", "Aucune modification du bac à sable enregistrée."],
        ["Modification applied; original backed up."] = ["Modification applied; original backed up.", "Wijziging toegepast; origineel geback-upt.", "Änderung angewendet; Original gesichert.", "Modification appliquée ; original sauvegardé."],
        ["Deletion captured but not applied."] = ["Deletion captured but not applied.", "Verwijdering vastgelegd maar niet toegepast.", "Löschung erfasst, aber nicht angewendet.", "Suppression enregistrée mais non appliquée."],
        ["Captured file content"] = ["Captured file content", "Vastgelegde bestandsinhoud", "Erfasster Dateiinhalt", "Contenu du fichier enregistré"],
        ["Original backups"] = ["Original backups", "Back-ups van originelen", "Originalsicherungen", "Sauvegardes des originaux"],
        ["Apply selected modifications"] = ["Apply selected modifications", "Geselecteerde wijzigingen toepassen", "Ausgewählte Änderungen anwenden", "Appliquer les modifications sélectionnées"],
        ["Binary content cannot be previewed."] = ["Binary content cannot be previewed.", "Binaire inhoud kan niet worden weergegeven.", "Binärinhalt kann nicht angezeigt werden.", "Le contenu binaire ne peut pas être prévisualisé."],
        ["Preview shortened."] = ["Preview shortened.", "Voorbeeld ingekort.", "Vorschau gekürzt.", "Aperçu raccourci."],
        ["Could not apply sandbox modification. Review conflicts and backups before retrying."] = ["Could not apply sandbox modification. Review conflicts and backups before retrying.", "Sandboxwijziging toepassen mislukt. Controleer conflicten en back-ups voordat je opnieuw probeert.", "Sandbox-Änderung konnte nicht angewendet werden. Prüfen Sie Konflikte und Sicherungen vor einem erneuten Versuch.", "Impossible d’appliquer la modification du bac à sable. Vérifiez les conflits et sauvegardes avant de réessayer."],
        ["OpenCode sandbox integration is not ready yet. Recorded permissions do not enable sandbox execution."] = ["OpenCode sandbox integration is not ready yet. Recorded permissions do not enable sandbox execution.", "De OpenCode-sandboxintegratie is nog niet klaar. Opgeslagen toestemmingen maken de sandbox nog niet beschikbaar.", "Die OpenCode-Sandbox-Integration ist noch nicht fertig. Gespeicherte Berechtigungen aktivieren die Sandbox nicht.", "L’intégration du bac à sable OpenCode n’est pas encore prête. Les autorisations enregistrées n’activent pas son exécution."],
        ["No sandbox permissions recorded."] = ["No sandbox permissions recorded.", "Geen sandbox-toestemmingen opgeslagen.", "Keine Sandbox-Berechtigungen gespeichert.", "Aucune autorisation de bac à sable enregistrée."],
        ["Permission revoked"] = ["Permission revoked", "Toestemming ingetrokken", "Berechtigung entzogen", "Autorisation révoquée"],
        ["Revoke permission and stop session"] = ["Revoke permission and stop session", "Toestemming intrekken en sessie stoppen", "Berechtigung entziehen und Sitzung stoppen", "Révoquer l’autorisation et arrêter la session"],
        ["Could not load sandbox permissions."] = ["Could not load sandbox permissions.", "Sandbox-toestemmingen laden mislukt.", "Sandbox-Berechtigungen konnten nicht geladen werden.", "Impossible de charger les autorisations du bac à sable."],
        ["Could not revoke sandbox permission."] = ["Could not revoke sandbox permission.", "Sandbox-toestemming intrekken mislukt.", "Sandbox-Berechtigung konnte nicht entzogen werden.", "Impossible de révoquer l’autorisation du bac à sable."],
        ["Sandbox unavailable"] = ["Sandbox unavailable", "Sandbox niet beschikbaar", "Sandbox nicht verfügbar", "Bac à sable indisponible"],
        ["Sandbox requested, but not active: OpenCode is blocked."] = ["Sandbox requested, but not active: OpenCode is blocked.", "Sandbox ingeschakeld, maar niet actief: OpenCode is geblokkeerd.", "Sandbox angefordert, aber nicht aktiv: OpenCode ist blockiert.", "Bac à sable demandé mais inactif : OpenCode est bloqué."],
        ["Sandbox isolation and permission requests are not available yet. No permissions can be granted or revoked."] = ["Sandbox isolation and permission requests are not available yet. No permissions can be granted or revoked.", "Sandbox-isolatie en toestemmingsverzoeken zijn nog niet beschikbaar. Er kunnen nog geen toestemmingen worden verleend of ingetrokken.", "Sandbox-Isolation und Berechtigungsanfragen sind noch nicht verfügbar. Es können noch keine Berechtigungen erteilt oder entzogen werden.", "L’isolation du bac à sable et les demandes d’autorisation ne sont pas encore disponibles. Aucune autorisation ne peut être accordée ou révoquée."],
        ["Sandbox is not implemented yet; OpenCode will not start while this is enabled."] = ["Sandbox is not implemented yet; OpenCode will not start while this is enabled.", "De sandbox is nog niet geïmplementeerd. OpenCode start niet zolang deze optie aanstaat.", "Die Sandbox ist noch nicht implementiert. OpenCode wird nicht gestartet, solange diese Option aktiviert ist.", "Le bac à sable n’est pas encore implémenté. OpenCode ne démarrera pas tant que cette option est activée."],
        ["Off: OpenCode runs with your normal Windows user access."] = ["Off: OpenCode runs with your normal Windows user access.", "Uit: OpenCode draait met de normale toegangsrechten van je Windows-account.", "Aus: OpenCode läuft mit den normalen Zugriffsrechten Ihres Windows-Kontos.", "Désactivé : OpenCode s’exécute avec les droits normaux de votre compte Windows."],
        ["OpenCode sandbox is enabled, but isolated execution is not available yet. OpenCode was not started."] = ["OpenCode sandbox is enabled, but isolated execution is not available yet. OpenCode was not started.", "De OpenCode-sandbox staat aan, maar geïsoleerd uitvoeren is nog niet beschikbaar. OpenCode is niet gestart.", "Die OpenCode-Sandbox ist aktiviert, aber isolierte Ausführung ist noch nicht verfügbar. OpenCode wurde nicht gestartet.", "Le bac à sable OpenCode est activé, mais l’exécution isolée n’est pas encore disponible. OpenCode n’a pas démarré."],
        ["Agent management"] = ["Agent management", "Agentbeheer", "Agent-Verwaltung", "Gestion des agents"],
        ["Agent update"] = ["Agent update", "Agentupdate", "Agent-Update", "Mise à jour de l’agent"],
        ["Update {0} from {1} to {2} is available."] = ["Update {0} from {1} to {2} is available.", "Update van {0} ({1} naar {2}) is beschikbaar.", "Update für {0} von {1} auf {2} ist verfügbar.", "La mise à jour de {0} ({1} vers {2}) est disponible."],
        ["Select {0} in the Agent tool dropdown below to review configuration warnings and update safely."] = ["Select {0} in the Agent tool dropdown below to review configuration warnings and update safely.", "Selecteer hieronder {0} bij Agent tool om configuratiewaarschuwingen te bekijken en veilig bij te werken.", "Wählen Sie unten {0} im Agent-Tool-Menü, um Konfigurationshinweise zu prüfen und sicher zu aktualisieren.", "Sélectionnez {0} dans la liste Agent ci-dessous pour examiner les avertissements de configuration et effectuer la mise à jour en toute sécurité."],
        ["Current terminal session: {0}"] = ["Current terminal session: {0}", "Huidige terminalsessie: {0}", "Aktuelle Terminalsitzung: {0}", "Session du terminal actuelle : {0}"],
        ["Recently viewed"] = ["Recently viewed", "Recent bekeken", "Kürzlich angesehen", "Récemment consultée"],
        ["No last-viewed session could be inferred. Select the session title that matches the OpenCode terminal before sharing."] = ["No last-viewed session could be inferred. Select the session title that matches the OpenCode terminal before sharing.", "De laatst bekeken sessie kon niet worden bepaald. Selecteer de titel die overeenkomt met de OpenCode-terminal voordat je deelt.", "Die zuletzt angesehene Sitzung konnte nicht ermittelt werden. Wählen Sie vor dem Teilen den Titel, der zum OpenCode-Terminal passt.", "Impossible de déterminer la dernière session consultée. Sélectionnez le titre correspondant au terminal OpenCode avant de partager."],
        ["CodeBadger cannot read the selected session ID from a newly started OpenCode TUI. Sessions are sorted by most recently viewed as a best guess; confirm the title before sharing."] = ["CodeBadger cannot read the selected session ID from a newly started OpenCode TUI. Sessions are sorted by most recently viewed as a best guess; confirm the title before sharing.", "CodeBadger kan de geselecteerde sessie-ID van een nieuw gestarte OpenCode-TUI niet uitlezen. Sessies staan op volgorde van laatst bekeken als beste schatting; controleer de titel vóór het delen.", "CodeBadger kann die ausgewählte Sitzungs-ID einer neu gestarteten OpenCode-TUI nicht auslesen. Sitzungen sind nach zuletzt angesehen sortiert; prüfen Sie den Titel vor dem Teilen.", "CodeBadger ne peut pas lire l’identifiant sélectionné d’une nouvelle session TUI OpenCode. Les sessions sont triées selon la dernière consultation ; vérifiez le titre avant le partage."],
        ["The current terminal session could not be confirmed in the OpenCode session list. Choose a session explicitly; the selected session will be shared, not necessarily the terminal currently on screen."] = ["The current terminal session could not be confirmed in the OpenCode session list. Choose a session explicitly; the selected session will be shared, not necessarily the terminal currently on screen.", "De huidige terminalsessie kon niet worden bevestigd in de OpenCode-sessielijst. Kies expliciet een sessie; de gekozen sessie is mogelijk niet de terminal die nu in beeld staat.", "Die aktuelle Terminalsitzung konnte in der OpenCode-Sitzungsliste nicht bestätigt werden. Wählen Sie ausdrücklich eine Sitzung; sie ist möglicherweise nicht die derzeit sichtbare Terminalsitzung.", "La session actuelle du terminal n’a pas pu être confirmée dans la liste OpenCode. Choisissez explicitement une session ; ce ne sera pas forcément celle affichée dans le terminal."],
        ["Check again"] = ["Check again", "Opnieuw controleren", "Erneut prüfen", "Vérifier à nouveau"],
        ["Check for agent updates"] = ["Check for agent updates", "Op agentupdates controleren", "Nach Agent-Updates suchen", "Rechercher des mises à jour des agents"],
        ["This update crosses a major version boundary. Review the migration guide and release notes carefully; configuration and behavior may change."] = ["This update crosses a major version boundary. Review the migration guide and release notes carefully; configuration and behavior may change.", "Deze update gaat over een major versiegrens heen. Bekijk de migratiehandleiding en releasenotes zorgvuldig; configuratie en gedrag kunnen veranderen.", "Dieses Update überschreitet eine Hauptversionsgrenze. Prüfen Sie Migrationsleitfaden und Versionshinweise sorgfältig; Konfiguration und Verhalten können sich ändern.", "Cette mise à jour franchit une version majeure. Consultez attentivement le guide de migration et les notes ; la configuration et le comportement peuvent changer."],
        ["OpenCode major-version migration guide"] = ["OpenCode major-version migration guide", "OpenCode-migratiehandleiding voor major versies", "OpenCode-Migrationsleitfaden für Hauptversionen", "Guide de migration majeure OpenCode"],
        ["Installed: {0}"] = ["Installed: {0}", "Geïnstalleerd: {0}", "Installiert: {0}", "Installée : {0}"],
        ["Latest: {0}"] = ["Latest: {0}", "Nieuwste: {0}", "Neueste: {0}", "Dernière : {0}"],
        ["Could not verify the latest version from the official release source. Update status is unknown."] = ["Could not verify the latest version from the official release source. Update status is unknown.", "De nieuwste versie kon niet bij de officiële bron worden gecontroleerd. De updatestatus is onbekend.", "Die neueste Version konnte nicht anhand der offiziellen Quelle überprüft werden. Der Update-Status ist unbekannt.", "Impossible de vérifier la dernière version auprès de la source officielle. L’état de mise à jour est inconnu."],
        ["The installed version could not be read from the detected command."] = ["The installed version could not be read from the detected command.", "De geïnstalleerde versie kon niet worden uitgelezen via de gevonden opdracht.", "Die installierte Version konnte über den gefundenen Befehl nicht gelesen werden.", "Impossible de lire la version installée à partir de la commande détectée."],
        ["OpenCode installation conflict"] = ["OpenCode installation conflict", "Conflicterende OpenCode-installaties", "OpenCode-Installationskonflikt", "Conflit d’installations OpenCode"],
        ["Try OpenCode activity check again"] = ["Try OpenCode activity check again", "OpenCode-activiteitscontrole opnieuw proberen", "OpenCode-Aktivitätsprüfung erneut versuchen", "Réessayer la vérification d’activité OpenCode"],
        ["OpenCode answered its health check but returned an empty session list, which CodeBadger cannot distinguish from an inaccessible database. Activity polling has been disabled for this launch."] = ["OpenCode answered its health check but returned an empty session list, which CodeBadger cannot distinguish from an inaccessible database. Activity polling has been disabled for this launch.", "OpenCode beantwoordde de controle, maar gaf geen sessies terug. CodeBadger kan dat niet onderscheiden van een ontoegankelijke database; activiteitscontrole is voor deze start uitgeschakeld.", "OpenCode beantwortete die Prüfung, lieferte aber keine Sitzungen. CodeBadger kann dies nicht von einer unzugänglichen Datenbank unterscheiden; die Aktivitätsabfrage wurde für diesen Start deaktiviert.", "OpenCode a répondu au contrôle, mais n’a renvoyé aucune session. CodeBadger ne peut pas distinguer cela d’une base de données inaccessible ; le suivi d’activité est désactivé pour ce lancement."],
        ["The OpenCode activity check failed again; activity polling remains disabled."] = ["The OpenCode activity check failed again; activity polling remains disabled.", "De OpenCode-activiteitscontrole is opnieuw mislukt; pollen blijft uitgeschakeld.", "Die OpenCode-Aktivitätsprüfung ist erneut fehlgeschlagen; die Abfrage bleibt deaktiviert.", "La vérification d’activité OpenCode a encore échoué ; le suivi reste désactivé."],
        ["OpenCode activity check did not find a session response. Polling stays disabled until a session is visible."] = ["OpenCode activity check did not find a session response. Polling stays disabled until a session is visible.", "De OpenCode-activiteitscontrole vond geen sessiereactie. Pollen blijft uit totdat er een sessie zichtbaar is.", "Die OpenCode-Aktivitätsprüfung fand keine Sitzungsantwort. Die Abfrage bleibt deaktiviert, bis eine Sitzung sichtbar ist.", "La vérification d’activité OpenCode n’a trouvé aucune réponse de session. Le suivi reste désactivé jusqu’à ce qu’une session soit visible."],
        ["Multiple OpenCode installations were detected. CodeBadger will use the working instance shown below. Other instances are not being polled."] = ["Multiple OpenCode installations were detected. CodeBadger will use the working instance shown below. Other instances are not being polled.", "Er zijn meerdere OpenCode-installaties gevonden. CodeBadger gebruikt de werkende instantie hieronder en blijft de andere instanties niet pollen.", "Es wurden mehrere OpenCode-Installationen erkannt. CodeBadger verwendet die unten angezeigte funktionierende Installation und fragt die anderen nicht wiederholt ab.", "Plusieurs installations OpenCode ont été détectées. CodeBadger utilisera l’instance fonctionnelle ci-dessous et ne réinterrogera pas les autres."],
        ["Multiple OpenCode installations were detected. CodeBadger uses the PATH-selected instance below. Failed instances are not polled again during this launch."] = ["Multiple OpenCode installations were detected. CodeBadger uses the PATH-selected instance below. Failed instances are not polled again during this launch.", "Er zijn meerdere OpenCode-installaties gevonden. CodeBadger gebruikt de instantie die PATH als eerste vindt. Mislukte instanties worden tijdens deze start niet opnieuw gepolld.", "Es wurden mehrere OpenCode-Installationen erkannt. CodeBadger verwendet die zuerst in PATH gefundene Instanz. Fehlgeschlagene Instanzen werden während dieses Starts nicht erneut abgefragt.", "Plusieurs installations OpenCode ont été détectées. CodeBadger utilise l’instance prioritaire dans PATH. Les instances en échec ne seront pas réinterrogées pendant ce lancement."],
        ["The OpenCode executable was detected, but its managed service did not pass the startup health check. CodeBadger will not keep polling it during this launch. Review the database and installation details below."] = ["The OpenCode executable was detected, but its managed service did not pass the startup health check. CodeBadger will not keep polling it during this launch. Review the database and installation details below.", "De OpenCode-executable is gevonden, maar de beheerde service slaagde niet voor de opstartcontrole. CodeBadger blijft deze tijdens deze start niet pollen. Bekijk hieronder de database- en installatie-informatie.", "Die OpenCode-Programmdatei wurde erkannt, aber der verwaltete Dienst bestand die Startprüfung nicht. CodeBadger fragt ihn während dieses Starts nicht weiter ab. Prüfen Sie unten die Datenbank- und Installationsinformationen.", "L’exécutable OpenCode a été détecté, mais le service géré n’a pas passé le contrôle au démarrage. CodeBadger ne continuera pas à l’interroger pendant ce lancement. Consultez les informations de base de données et d’installation ci-dessous."],
        ["OpenCode answered its health check but returned an empty session list, which CodeBadger cannot distinguish from an inaccessible database. Activity polling has been disabled for this launch."] = ["OpenCode answered its health check but returned an empty session list, which CodeBadger cannot distinguish from an inaccessible database. Activity polling has been disabled for this launch.", "OpenCode beantwoordde de controle, maar gaf geen sessies terug. CodeBadger kan dat niet onderscheiden van een ontoegankelijke database; activiteitscontrole is voor deze start uitgeschakeld.", "OpenCode beantwortete die Prüfung, lieferte aber keine Sitzungen. CodeBadger kann dies nicht von einer unzugänglichen Datenbank unterscheiden; die Aktivitätsabfrage wurde für diesen Start deaktiviert.", "OpenCode a répondu au contrôle, mais n’a renvoyé aucune session. CodeBadger ne peut pas distinguer cela d’une base de données inaccessible ; le suivi d’activité est désactivé pour ce lancement."],
        ["Working instance"] = ["Working instance", "Werkende instantie", "Funktionierende Instanz", "Instance fonctionnelle"],
        ["Not responding"] = ["Not responding", "Reageert niet", "Antwortet nicht", "Ne répond pas"],
        ["Used by CodeBadger"] = ["Used by CodeBadger", "Gebruikt door CodeBadger", "Von CodeBadger verwendet", "Utilisée par CodeBadger"],
        ["Version {0} · installed with {1}"] = ["Version {0} · installed with {1}", "Versie {0} · geïnstalleerd met {1}", "Version {0} · installiert mit {1}", "Version {0} · installée avec {1}"],
        ["NVM Node version: {0}"] = ["NVM Node version: {0}", "NVM Node-versie: {0}", "NVM-Node-Version: {0}", "Version Node NVM : {0}"],
        ["CodeBadger uses only the selected working executable; it does not poll failed instances again during this launch. Existing sessions and history remain in the shared OpenCode data directory, but sessions may not appear if the selected installation uses a different data directory. Avoid uninstalling or deleting OpenCode data until you have backed it up."] = ["CodeBadger uses only the selected working executable; it does not poll failed instances again during this launch. Existing sessions and history remain in the shared OpenCode data directory, but sessions may not appear if the selected installation uses a different data directory. Avoid uninstalling or deleting OpenCode data until you have backed it up.", "CodeBadger gebruikt alleen de gekozen werkende executable en blijft de defecte instanties deze start niet pollen. Sessies en geschiedenis blijven in de gedeelde OpenCode-datamap, maar kunnen ontbreken als de gekozen installatie een andere datamap gebruikt. Verwijder geen installatie- of databestanden zonder eerst een back-up te maken.", "CodeBadger verwendet nur die ausgewählte funktionierende Programmdatei und fragt fehlerhafte Instanzen während dieses Starts nicht erneut ab. Sitzungen und Verlauf bleiben im gemeinsamen OpenCode-Datenordner, können aber fehlen, wenn die ausgewählte Installation einen anderen Datenordner verwendet. Deinstallieren oder löschen Sie keine OpenCode-Daten ohne vorherige Sicherung.", "CodeBadger utilise uniquement l’exécutable fonctionnel sélectionné et ne réinterrogera pas les instances défaillantes pendant ce lancement. Les sessions et l’historique restent dans le dossier de données OpenCode partagé, mais peuvent être absents si l’installation sélectionnée utilise un autre dossier. Ne désinstallez et ne supprimez pas les données OpenCode avant de les sauvegarder."],
        ["CodeBadger uses the PATH-selected executable and probes only the managed OpenCode service once at startup. A failed database health check disables activity polling; OpenCode CLI sessions may continue independently, but activity indicators and Slack completion detection will not work."] = ["CodeBadger uses the PATH-selected executable and probes only the managed OpenCode service once at startup. A failed database health check disables activity polling; OpenCode CLI sessions may continue independently, but activity indicators and Slack completion detection will not work.", "CodeBadger gebruikt de executable die PATH als eerste vindt en controleert de beheerde OpenCode-service één keer bij het opstarten. Bij een mislukte databasecontrole stopt het pollen; OpenCode-terminalsessies kunnen zelfstandig doorgaan, maar activiteitsindicatoren en Slack-klaarmeldingen werken dan niet.", "CodeBadger verwendet die zuerst in PATH gefundene Programmdatei und prüft den verwalteten OpenCode-Dienst einmal beim Start. Bei einer fehlgeschlagenen Datenbankprüfung wird die Aktivitätsabfrage deaktiviert; OpenCode-Terminalsitzungen können unabhängig weiterlaufen, aber Aktivitätsanzeigen und Slack-Abschlussmeldungen funktionieren dann nicht.", "CodeBadger utilise l’exécutable trouvé en premier dans PATH et vérifie une seule fois au démarrage le service OpenCode géré. Si le contrôle de la base échoue, le suivi est désactivé ; les sessions CLI OpenCode peuvent continuer, mais les indicateurs d’activité et les notifications Slack de fin ne fonctionneront pas."],
        ["To resolve the conflict, choose one installation method, keep its command first on PATH, and update or uninstall the other using that same package manager. NVM/nvm4w installations are linked to a Node version; global packages may exist separately in each Node version."] = ["To resolve the conflict, choose one installation method, keep its command first on PATH, and update or uninstall the other using that same package manager. NVM/nvm4w installations are linked to a Node version; global packages may exist separately in each Node version.", "Los dit op door één installatiemethode te kiezen en die opdracht vooraan op PATH te zetten. Werk de andere installatie bij of verwijder die met dezelfde pakketbeheerder. NVM/nvm4w-installaties horen bij een Node-versie; globale pakketten kunnen per Node-versie apart bestaan.", "Wählen Sie zur Behebung eine Installationsmethode und setzen Sie deren Befehl an den Anfang von PATH. Aktualisieren oder entfernen Sie die andere Installation mit demselben Paketmanager. NVM/nvm4w-Installationen sind an eine Node-Version gebunden; globale Pakete können je Node-Version getrennt vorliegen.", "Pour résoudre le conflit, choisissez une méthode d’installation et placez sa commande en premier dans PATH. Mettez à jour ou désinstallez l’autre avec le même gestionnaire de paquets. Les installations NVM/nvm4w sont liées à une version de Node ; les paquets globaux peuvent différer selon la version de Node."],
        ["Release notes do not cover the installed version. Potential breaking changes could not be verified; review all notes before updating."] = ["Release notes do not cover the installed version. Potential breaking changes could not be verified; review all notes before updating.", "De releasenotes dekken de geïnstalleerde versie niet. Mogelijke incompatibele wijzigingen konden niet worden gecontroleerd; bekijk alle notities vóór de update.", "Die Versionshinweise decken die installierte Version nicht ab. Mögliche inkompatible Änderungen konnten nicht überprüft werden; prüfen Sie vor dem Update alle Hinweise.", "Les notes de version ne couvrent pas la version installée. Les changements incompatibles éventuels n’ont pas pu être vérifiés ; consultez toutes les notes avant la mise à jour."],
        ["The release notes mention configuration, migration, deprecation, or breaking changes. Review the notes and check your config before updating."] = ["The release notes mention configuration, migration, deprecation, or breaking changes. Review the notes and check your config before updating.", "De releasenotes noemen configuratie-, migratie-, uitfasering- of incompatibele wijzigingen. Bekijk de notities en controleer je configuratie vóór de update.", "Die Versionshinweise erwähnen Konfigurations-, Migrations-, Deprecation- oder inkompatible Änderungen. Prüfen Sie die Hinweise und Ihre Konfiguration vor dem Update.", "Les notes mentionnent des changements de configuration, de migration, de dépréciation ou incompatibles. Consultez-les et vérifiez votre configuration avant la mise à jour."],
        ["No configuration-breaking changes were identified in the official release notes. This is not a guarantee; review the release notes before updating."] = ["No configuration-breaking changes were identified in the official release notes. This is not a guarantee; review the release notes before updating.", "In de officiële releasenotes zijn geen incompatibele configuratiewijzigingen gevonden. Dit is geen garantie; bekijk de releasenotes vóór de update.", "In den offiziellen Versionshinweisen wurden keine inkompatiblen Konfigurationsänderungen gefunden. Dies ist keine Garantie; prüfen Sie die Versionshinweise vor dem Update.", "Aucun changement de configuration incompatible n’a été identifié dans les notes officielles. Ce n’est pas une garantie ; consultez les notes avant la mise à jour."],
        ["Review official release notes"] = ["Review official release notes", "Officiële releasenotes bekijken", "Offizielle Versionshinweise prüfen", "Consulter les notes officielles"],
        ["Preparing update..."] = ["Preparing update...", "Update voorbereiden...", "Update wird vorbereitet...", "Préparation de la mise à jour..."],
        ["Back up config and open update terminal"] = ["Back up config and open update terminal", "Configuratie back-uppen en updateterminal openen", "Konfiguration sichern und Update-Terminal öffnen", "Sauvegarder la configuration et ouvrir le terminal de mise à jour"],
        ["Agent is up to date."] = ["Agent is up to date.", "De agent is up-to-date.", "Der Agent ist auf dem neuesten Stand.", "L’agent est à jour."],
        ["Checking official agent releases..."] = ["Checking official agent releases...", "Officiële agentreleases controleren...", "Offizielle Agent-Releases werden geprüft...", "Vérification des versions officielles des agents..."],
        ["Close all OpenCode sessions and terminals before updating."] = ["Close all OpenCode sessions and terminals before updating.", "Sluit alle OpenCode-sessies en terminals vóór de update.", "Schließen Sie vor dem Update alle OpenCode-Sitzungen und Terminals.", "Fermez toutes les sessions et tous les terminaux OpenCode avant la mise à jour."],
        ["Could not verify OpenCode processes. Close any OpenCode session and retry; the update was not started."] = ["Could not verify OpenCode processes. Close any OpenCode session and retry; the update was not started.", "OpenCode-processen konden niet worden gecontroleerd. Sluit eventuele OpenCode-sessies en probeer opnieuw; de update is niet gestart.", "OpenCode-Prozesse konnten nicht überprüft werden. Schließen Sie alle OpenCode-Sitzungen und versuchen Sie es erneut; das Update wurde nicht gestartet.", "Impossible de vérifier les processus OpenCode. Fermez toute session OpenCode et réessayez ; la mise à jour n’a pas été lancée."],
        ["Confirm that no OpenCode session has unsaved work. CodeBadger will stop all OpenCode sessions and background processes, run the update, then restart the OpenCode background service. Unsaved session work may be lost."] = ["Confirm that no OpenCode session has unsaved work. CodeBadger will stop all OpenCode sessions and background processes, run the update, then restart the OpenCode background service. Unsaved session work may be lost.", "Bevestig dat er geen OpenCode-sessie is met niet-opgeslagen werk. CodeBadger stopt alle OpenCode-sessies en achtergrondprocessen, voert de update uit en start daarna de OpenCode-achtergrondservice opnieuw. Niet-opgeslagen werk kan verloren gaan.", "Bestätigen Sie, dass keine OpenCode-Sitzung ungespeicherte Arbeit enthält. CodeBadger beendet alle OpenCode-Sitzungen und Hintergrundprozesse, führt das Update aus und startet anschließend den OpenCode-Hintergrunddienst erneut. Nicht gespeicherte Arbeit kann verloren gehen.", "Confirmez qu’aucune session OpenCode ne contient de travail non enregistré. CodeBadger arrêtera toutes les sessions et tous les processus d’arrière-plan OpenCode, effectuera la mise à jour puis redémarrera le service OpenCode. Le travail non enregistré peut être perdu."],
        ["Stop OpenCode, back up and update"] = ["Stop OpenCode, back up and update", "OpenCode stoppen, back-up maken en bijwerken", "OpenCode beenden, sichern und aktualisieren", "Arrêter OpenCode, sauvegarder et mettre à jour"],
        ["The release notes indicate possible configuration changes, or could not be checked across every version. Back up configs and review the official notes first. Continue?"] = ["The release notes indicate possible configuration changes, or could not be checked across every version. Back up configs and review the official notes first. Continue?", "De releasenotes wijzen op mogelijke configuratiewijzigingen, of konden niet voor alle tussenliggende versies worden gecontroleerd. Maak een back-up en bekijk eerst de officiële notities. Doorgaan?", "Die Versionshinweise deuten auf mögliche Konfigurationsänderungen hin oder konnten nicht für alle Zwischenversionen geprüft werden. Sichern Sie die Konfiguration und prüfen Sie zuerst die offiziellen Hinweise. Fortfahren?", "Les notes indiquent des changements de configuration possibles ou n’ont pas pu être vérifiées pour toutes les versions intermédiaires. Sauvegardez la configuration et consultez d’abord les notes officielles. Continuer ?"],
        ["No configuration-breaking changes were identified in the available official release notes, but this is not guaranteed. Back up configs and review the notes before continuing."] = ["No configuration-breaking changes were identified in the available official release notes, but this is not guaranteed. Back up configs and review the notes before continuing.", "In de beschikbare officiële releasenotes zijn geen incompatibele configuratiewijzigingen gevonden, maar dit is geen garantie. Maak een back-up en bekijk de notities voordat je doorgaat.", "In den verfügbaren offiziellen Versionshinweisen wurden keine inkompatiblen Konfigurationsänderungen gefunden, dies ist jedoch keine Garantie. Sichern Sie die Konfiguration und prüfen Sie die Hinweise, bevor Sie fortfahren.", "Aucun changement incompatible n’a été identifié dans les notes officielles disponibles, mais ce n’est pas une garantie. Sauvegardez la configuration et consultez les notes avant de continuer."],
        ["Detected Hermes config.yaml, including HERMES_HOME, will be archived."] = ["Detected Hermes config.yaml, including HERMES_HOME, will be archived.", "De gevonden Hermes config.yaml (ook via HERMES_HOME) wordt gearchiveerd.", "Die gefundene Hermes-config.yaml (einschließlich HERMES_HOME) wird archiviert.", "Le fichier config.yaml Hermes détecté (y compris via HERMES_HOME) sera archivé."],
        ["Detected global and configured repository config files will be archived."] = ["Detected global and configured repository config files will be archived.", "Gevonden globale configuratiebestanden en repositoryconfiguraties worden gearchiveerd.", "Erkannte globale Konfigurationsdateien und Repository-Konfigurationen werden archiviert.", "Les fichiers de configuration globaux et des dépôts détectés seront archivés."],
        ["The terminal performs the tool's official update command; CodeBadger will not update configuration files automatically."] = ["The terminal performs the tool's official update command; CodeBadger will not update configuration files automatically.", "De terminal voert het officiële updatecommando van de tool uit; CodeBadger past configuratiebestanden niet automatisch aan.", "Das Terminal führt den offiziellen Update-Befehl des Tools aus; CodeBadger ändert Konfigurationsdateien nicht automatisch.", "Le terminal exécute la commande officielle de mise à jour de l’outil ; CodeBadger ne modifie pas automatiquement les fichiers de configuration."],
        ["Update {0} to {1}?"] = ["Update {0} to {1}?", "{0} bijwerken naar {1}?", "{0} auf {1} aktualisieren?", "Mettre à jour {0} vers {1} ?"],
