        ["Faster Git status"] = ["Faster Git status", "Snellere Git-status", "Schnellerer Git-Status", "Statut Git plus rapide"],
        ["These repository-local options can speed up status checks on supported file systems. Enable them only if they work correctly in your environment."] = ["These repository-local options can speed up status checks on supported file systems. Enable them only if they work correctly in your environment.", "Deze repositorylokale opties kunnen statuscontroles op ondersteunde bestandssystemen versnellen. Schakel ze alleen in als ze goed werken in jouw omgeving.", "Diese repositorylokalen Optionen können Statusprüfungen auf unterstützten Dateisystemen beschleunigen. Aktivieren Sie sie nur, wenn sie in Ihrer Umgebung korrekt funktionieren.", "Ces options propres au dépôt peuvent accélérer les vérifications sur les systèmes de fichiers pris en charge. Activez-les uniquement si elles fonctionnent correctement dans votre environnement."],
        ["Use Git file system monitor"] = ["Use Git file system monitor", "Git-bestandssysteemmonitor gebruiken", "Git-Dateisystemmonitor verwenden", "Utiliser le moniteur du système de fichiers Git"],
        ["The built-in file system monitor requires Git 2.37 or newer. External monitors can be configured separately."] = ["The built-in file system monitor requires Git 2.37 or newer. External monitors can be configured separately.", "De ingebouwde bestandssysteemmonitor vereist Git 2.37 of nieuwer. Externe monitors kun je apart instellen.", "Der integrierte Dateisystemmonitor erfordert Git 2.37 oder neuer. Externe Monitore können separat konfiguriert werden.", "Le moniteur intégré du système de fichiers nécessite Git 2.37 ou une version ultérieure. Les moniteurs externes peuvent être configurés séparément."],
        ["Use Git untracked cache"] = ["Use Git untracked cache", "Git-cache voor onbeheerde bestanden gebruiken", "Git-Cache für nicht versionierte Dateien verwenden", "Utiliser le cache Git des fichiers non suivis"],
        ["Git status optimization setting updated."] = ["Git status optimization setting updated.", "Git-statusoptimalisatie bijgewerkt.", "Git-Statusoptimierungseinstellung aktualisiert.", "Paramètre d’optimisation du statut Git mis à jour."],
        ["Could not update Git status optimization: {0}"] = ["Could not update Git status optimization: {0}", "Git-statusoptimalisatie bijwerken mislukt: {0}", "Git-Statusoptimierung konnte nicht aktualisiert werden: {0}", "Impossible de mettre à jour l’optimisation du statut Git : {0}"],
        ["Git maintenance optimizes local storage and commit indexes. It does not delete branches or rewrite commit history."] = ["Git maintenance optimizes local storage and commit indexes. It does not delete branches or rewrite commit history.", "Git-onderhoud optimaliseert lokale opslag en commit-indexen. Het verwijdert geen branches en herschrijft de commitgeschiedenis niet.", "Die Git-Wartung optimiert den lokalen Speicher und Commit-Indizes. Sie löscht keine Branches und schreibt die Commit-Historie nicht um.", "La maintenance Git optimise le stockage local et les index de commits. Elle ne supprime pas de branches et ne réécrit pas l’historique."],
        ["Running maintenance..."] = ["Running maintenance...", "Onderhoud uitvoeren...", "Wartung läuft...", "Maintenance en cours..."],
        ["Run Git maintenance"] = ["Run Git maintenance", "Git-onderhoud uitvoeren", "Git-Wartung ausführen", "Lancer la maintenance Git"],
        ["Prune remote references"] = ["Prune remote references", "Remote-verwijzingen opschonen", "Remote-Referenzen bereinigen", "Nettoyer les références distantes"],
