        ["Old merged local branches"] = ["Old merged local branches", "Oude gemergde lokale branches", "Alte gemergte lokale Branches", "Anciennes branches locales fusionnées"],
        ["Candidates are checked against the detected default branch '{0}' and inactive for at least 90 days. Protected branches are excluded."] = ["Candidates are checked against the detected default branch '{0}' and inactive for at least 90 days. Protected branches are excluded.", "Kandidaten worden gecontroleerd tegen de herkende standaardbranch '{0}' en zijn minstens 90 dagen inactief. Beschermde branches zijn uitgesloten.", "Kandidaten werden anhand des erkannten Standard-Branches '{0}' geprüft und sind seit mindestens 90 Tagen inaktiv. Geschützte Branches sind ausgeschlossen.", "Les candidates sont vérifiées par rapport à la branche par défaut détectée « {0} » et sont inactives depuis au moins 90 jours. Les branches protégées sont exclues."],
        ["Could not detect the default branch. Branch candidates cannot be safely determined."] = ["Could not detect the default branch. Branch candidates cannot be safely determined.", "De standaardbranch kon niet worden herkend. Branchkandidaten kunnen daarom niet veilig worden bepaald.", "Der Standard-Branch konnte nicht erkannt werden. Branch-Kandidaten können daher nicht sicher bestimmt werden.", "Impossible de détecter la branche par défaut. Les branches candidates ne peuvent pas être déterminées en toute sécurité."],
        ["Set the remote default branch (origin/HEAD), or ensure a local main, master, develop, or development branch exists, then refresh candidates."] = ["Set the remote default branch (origin/HEAD), or ensure a local main, master, develop, or development branch exists, then refresh candidates.", "Stel de standaardbranch van de remote in (origin/HEAD), of zorg dat lokaal main, master, develop of development bestaat en vernieuw daarna de kandidaten.", "Legen Sie den Standard-Branch des Remotes fest (origin/HEAD) oder stellen Sie sicher, dass lokal main, master, develop oder development vorhanden ist, und aktualisieren Sie dann die Kandidaten.", "Définissez la branche par défaut distante (origin/HEAD) ou assurez-vous qu’une branche locale main, master, develop ou development existe, puis actualisez les candidates."],
        ["Branch cleanup changes local references"] = ["Branch cleanup changes local references", "Branches opruimen wijzigt lokale verwijzingen", "Branch-Bereinigung ändert lokale Referenzen", "Le nettoyage des branches modifie les références locales"],
        ["Only local branches are removed. Remote branches are not changed."] = ["Only local branches are removed. Remote branches are not changed.", "Alleen lokale branches worden verwijderd. Remote branches blijven ongewijzigd.", "Es werden nur lokale Branches entfernt. Remote-Branches bleiben unverändert.", "Seules les branches locales sont supprimées. Les branches distantes ne sont pas modifiées."],
        ["Removing a branch does not delete commits from shared history, but an unmerged branch may contain work you still need. Review candidates and keep a backup if unsure."] = ["Removing a branch does not delete commits from shared history, but an unmerged branch may contain work you still need. Review candidates and keep a backup if unsure.", "Een branch verwijderen wist geen commits uit gedeelde geschiedenis, maar een niet-gemergde branch kan werk bevatten dat je nog nodig hebt. Controleer kandidaten en maak bij twijfel een backup.", "Das Entfernen eines Branches löscht keine Commits aus der gemeinsamen Historie, aber ein nicht integrierter Branch kann noch benötigte Arbeit enthalten. Prüfen Sie die Kandidaten und erstellen Sie im Zweifel eine Sicherung.", "La suppression d’une branche n’efface pas les commits de l’historique partagé, mais une branche non fusionnée peut contenir du travail utile. Vérifiez les candidates et faites une sauvegarde en cas de doute."],
        ["Safe local optimization: this does not remove branches or rewrite commit history."] = ["Safe local optimization: this does not remove branches or rewrite commit history.", "Veilige lokale optimalisatie: dit verwijdert geen branches en herschrijft geen commitgeschiedenis.", "Sichere lokale Optimierung: Es werden keine Branches entfernt und keine Commit-Historie umgeschrieben.", "Optimisation locale sûre : aucune branche n’est supprimée et l’historique des commits n’est pas réécrit."],
        ["Refresh candidates"] = ["Refresh candidates", "Kandidaten vernieuwen", "Kandidaten aktualisieren", "Actualiser les candidates"],
        ["Remove selected ({0})"] = ["Remove selected ({0})", "Selectie verwijderen ({0})", "Auswahl entfernen ({0})", "Supprimer la sélection ({0})"],
        ["Remove selected local ({0})"] = ["Remove selected local ({0})", "Geselecteerde lokale verwijderen ({0})", "Ausgewählte lokale entfernen ({0})", "Supprimer les locales sélectionnées ({0})"],
        ["Remove all"] = ["Remove all", "Alles verwijderen", "Alle entfernen", "Tout supprimer"],
        ["Remove all listed local branches"] = ["Remove all listed local branches", "Alle getoonde lokale branches verwijderen", "Alle angezeigten lokalen Branches entfernen", "Supprimer toutes les branches locales affichées"],
        ["Select all branches"] = ["Select all branches", "Alle branches selecteren", "Alle Branches auswählen", "Sélectionner toutes les branches"],
        ["Remove all old merged branches?"] = ["Remove all old merged branches?", "Alle oude gemergde branches verwijderen?", "Alle alten gemergten Branches entfernen?", "Supprimer toutes les anciennes branches fusionnées ?"],
        ["Remove all listed old merged local branches?"] = ["Remove all listed old merged local branches?", "Alle getoonde oude gemergde lokale branches verwijderen?", "Alle angezeigten alten gemergten lokalen Branches entfernen?", "Supprimer toutes les anciennes branches locales fusionnées affichées ?"],
        ["Remove all {0} old merged local branches? Each branch will be checked again and Git will refuse removal if it is not safely merged."] = ["Remove all {0} old merged local branches? Each branch will be checked again and Git will refuse removal if it is not safely merged.", "Alle {0} oude gemergde lokale branches verwijderen? Elke branch wordt opnieuw gecontroleerd; Git weigert verwijdering als die niet veilig is gemergd.", "Alle {0} alten gemergten lokalen Branches entfernen? Jeder Branch wird erneut geprüft; Git verweigert die Entfernung, wenn er nicht sicher integriert ist.", "Supprimer les {0} anciennes branches locales fusionnées ? Chaque branche sera vérifiée à nouveau et Git refusera sa suppression si elle n’est pas fusionnée en toute sécurité."],
